// <auto-generated/>
using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Data;
using TplCore.Element;


/// <summary>
/// Summary description for CurrencyFilter
/// </summary>
/// 
namespace Fanex.Age.UI.Components
{
    using CurrencyFilter;
    public class CurrencyFilter_Control : IComponent
    {
        CurrencyFilter_Template tpl = new CurrencyFilter_Template();
        public CurrencyFilter_Control(DataTable dtb, string currencyId)
        {
            tpl.CurrencyText = Resources.Lang.currency;
            GenerateControl(dtb, currencyId);
        }
        public static implicit operator string(CurrencyFilter_Control value)
        {
            return value.ToString();
        }
        public void HideLinkedResources()
        {
            
        }
        public override string ToString()
        {
            return tpl.ToString();
        }

        private DataTable GenerateDataTable(DataTable dtb)
        {
            DataTable newdtb = new DataTable();
            newdtb.Columns.Add("currency", typeof(String));
            newdtb.Columns.Add("currencyname", typeof(String));

            DataRow newRow = newdtb.NewRow();
            newRow["currency"] = 0;
            newRow["currencyname"] = Resources.Lang.all;
            newdtb.Rows.Add(newRow);

            newRow = newdtb.NewRow();
            newRow["currency"] = -2;
            newRow["currencyname"] = Resources.Lang.basecurrency + " RM";
            newdtb.Rows.Add(newRow);

            newRow = newdtb.NewRow();
            newRow["currency"] = -3;
            newRow["currencyname"] = Resources.Lang.basecurrency + " US$";
            newdtb.Rows.Add(newRow);

            foreach (DataRow dr in dtb.Rows)
            {
                newRow = newdtb.NewRow();
                newRow["currency"] = dr["currency"];
                newRow["currencyname"] = dr["currencyname"];
                newdtb.Rows.Add(newRow);
            }
            return newdtb;
        }

        private void GenerateControl(DataTable dtb, string currencyId)
        {
            CurrencyFilter_options_Block tplOption = new CurrencyFilter_options_Block();
            tpl.options.Clear();
            if (dtb.Rows.Count > 0)
            {
                DataTable NewDatatable = GenerateDataTable(dtb);
                int counter = NewDatatable.Rows.Count;
                for (int i = 0; i < counter; i++)
                {

                    tplOption.OptionText = NewDatatable.Rows[i]["currencyname"].ToString();
                    tplOption.OptionValue = NewDatatable.Rows[i]["currency"].ToString();
                    if (NewDatatable.Rows[i]["currency"].ToString().CompareTo(currencyId) == 0)
                        tplOption.selected = "Selected";
                    else
                        tplOption.selected = string.Empty;
                    tpl.options.Append(tplOption);
                }
            }
            else
            {
                tplOption.OptionText = Sunplus.Agent.Model.Entities.UserSession.Current.Currency;
                tplOption.OptionValue = Sunplus.Agent.Model.Entities.UserSession.Current.CurrencyId.ToString();
                tpl.options.selected = "Selected";
                tpl.options = tplOption;
            }

        }
    }
}
